import{_ as a,o as n,c as t,a6 as i}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"水合 · 把死的 HTML 救活","description":"服务端发来的 HTML 看得见却点不动——它是「死」的。水合(hydration)让客户端 JS 接管这份 HTML，装上事件、恢复状态，把它唤醒成可交互应用。这一章讲透水合的原理、它的「恐怖谷」、以及最坑的水合失配。","frontmatter":{"title":"水合 · 把死的 HTML 救活","description":"服务端发来的 HTML 看得见却点不动——它是「死」的。水合(hydration)让客户端 JS 接管这份 HTML，装上事件、恢复状态，把它唤醒成可交互应用。这一章讲透水合的原理、它的「恐怖谷」、以及最坑的水合失配。","source":"https://daiw.org/manual/ssr/hydration"},"headers":[],"relativePath":"manual/computer-programming/ssr/hydration.md","filePath":"manual/computer-programming/ssr/hydration.md"}'),r={name:"manual/computer-programming/ssr/hydration.md"};function e(l,s,o,p,h,d){return n(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="水合-·-把死的-html-救活" tabindex="-1">水合 · 把死的 HTML 救活 <a class="header-anchor" href="#水合-·-把死的-html-救活" aria-label="Permalink to &quot;水合 · 把死的 HTML 救活&quot;">​</a></h1><p>服务端发来的 HTML 看得见却点不动——它是「死」的。水合(hydration)让客户端 JS 接管这份 HTML，装上事件、恢复状态，把它唤醒成可交互应用。这一章讲透水合的原理、它的「恐怖谷」、以及最坑的水合失配。</p><p>上一章说，SSR 让服务器发来一份带内容的 HTML，浏览器立刻能<strong>显示</strong>。但有个残酷的真相：这份 HTML 此刻是「<strong>死</strong>」的——你能看到按钮，但<strong>点了没反应</strong>；能看到输入框，但<strong>打不了字</strong>。因为服务端产出的只是一段<strong>静态文本</strong>，上面没有任何事件监听、没有任何 JavaScript 状态。</p><p>把这份「死」HTML 唤醒成一个「活」的、能交互的应用，靠的就是<strong>水合(hydration)</strong>。</p><h2 id="水合到底在做什么" tabindex="-1">水合到底在做什么 <a class="header-anchor" href="#水合到底在做什么" aria-label="Permalink to &quot;水合到底在做什么&quot;">​</a></h2><p>浏览器显示完首屏后，后台会下载那包 JS。JS 跑起来后，框架(React / Vue / Svelte)做一件事：<strong>不是把页面重画一遍，而是「接管」已经存在的 HTML。</strong></p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[&quot;服务端 HTML&lt;br/&gt;看得见 · 点不动&quot;] --&gt; B[&quot;下载并执行 JS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[&quot;框架重建组件树&lt;br/&gt;与现有 DOM 对齐&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[&quot;挂上事件监听&lt;br/&gt;恢复状态&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt; E[&quot;活的应用&lt;br/&gt;可点击 · 可交互&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>具体说，React 会在客户端<strong>再渲染一遍相同的组件树</strong>，然后拿这次的结果去<strong>匹配</strong>服务端已经放在页面上的 DOM——匹配得上，就<strong>不重建 DOM</strong>（那样会闪、会丢状态），而是**「认领」现有节点**，只把事件监听器挂上去。于是同一批 DOM 节点，从「死的文本」变成了「活的、连着 React 的组件」。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>水合 ≈ 「对暗号接管」。</strong> 服务端先把 HTML 摆好（布景已就位），客户端 JS 来了之后，拿着同一套组件代码「对暗号」：确认每个 DOM 节点该归哪个组件管，然后接上电（事件、状态）。整个过程复用现有 DOM，所以用户几乎察觉不到画面变化——变的是「能不能交互」。</p></div><h2 id="恐怖谷-看得见-点不动" tabindex="-1">恐怖谷：看得见，点不动 <a class="header-anchor" href="#恐怖谷-看得见-点不动" aria-label="Permalink to &quot;恐怖谷：看得见，点不动&quot;">​</a></h2><p>水合最反直觉的地方，是它制造了一段**「看得见却点不动」的窗口期**：</p><ul><li><strong>首屏 HTML 到达</strong> → 用户看到了内容（FCP 达成）。</li><li><strong>但 JS 还在下载 / 执行 / 水合中</strong> → 页面上的交互全是<strong>哑的</strong>：点按钮没反应、点链接可能没跳转、表单填不了。</li><li><strong>水合完成</strong> → 页面才真正「活」过来（TTI，可交互时间达成）。</li></ul><p>这段 FCP 和 TTI 之间的空档，是 SSR 特有的「恐怖谷」：内容看起来已经好了，用户去点却发现没反应，体验割裂。<strong>应用越大、JS 越多，这段空档越长。</strong> 缓解它，正是后面<a href="/Front2Full/manual/computer-programming/ssr/streaming">流式渲染</a>、<a href="/Front2Full/manual/computer-programming/ssr/server-components">服务端组件</a>要解决的核心问题之一。</p><h2 id="水合的代价-一遍活干两次" tabindex="-1">水合的代价：一遍活干两次 <a class="header-anchor" href="#水合的代价-一遍活干两次" aria-label="Permalink to &quot;水合的代价：一遍活干两次&quot;">​</a></h2><p>水合不便宜。为了「认领」DOM，客户端得<strong>把所有组件再渲染一遍</strong>——服务端已经渲染过一次了，客户端又来一次，同一份渲染逻辑<strong>跑了两遍</strong>。对一个大型应用，这一遍客户端渲染是<strong>又慢又占 CPU</strong>的，而且它往往是<strong>阻塞</strong>的：水合没做完，主线程忙着，页面就卡着。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>这就是「<strong>同构的双刃</strong>」：同一套代码在两端各跑一遍，换来了 SSR 的首屏优势，却也带来了「客户端要把活重做一遍」的开销。整个 SSR 生态这些年的进化——流式水合、选择性水合、岛屿架构、服务端组件——很大程度上都是在回答同一个问题：<strong>能不能少水合一点、或者晚一点、或者只水合真正需要交互的那部分？</strong> 这条线索，我们在第二站会顺着讲。</p></div><h2 id="最坑的坑-水合失配" tabindex="-1">最坑的坑：水合失配 <a class="header-anchor" href="#最坑的坑-水合失配" aria-label="Permalink to &quot;最坑的坑：水合失配&quot;">​</a></h2><p>水合要求<strong>服务端渲染的结果</strong>和<strong>客户端首次渲染的结果</strong>必须<strong>一模一样</strong>——因为客户端是拿自己的渲染去「对齐」服务端的 DOM。一旦两边对不上，就是<strong>水合失配(hydration mismatch)</strong>，React 会告警，甚至丢弃服务端 HTML 重画（前功尽弃 + 闪烁）。</p><p>什么会导致两边不一致？<strong>任何「在服务端和客户端会算出不同结果」的代码</strong>：</p><div class="language-jsx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✗ 会失配:服务端渲染时和客户端水合时,时间不同</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Date</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toLocaleString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✗ 会失配:服务端没有 window</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{window.innerWidth}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✗ 会失配:服务端不知道用户本地时区 / 语言</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Intl.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">NumberFormat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x)}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li><strong>时间 / 随机数</strong>：<code>Date.now()</code>、<code>Math.random()</code> 每次不同。</li><li><strong>浏览器专属 API</strong>：<code>window</code>、<code>localStorage</code>、<code>navigator</code> 在服务端根本不存在。</li><li><strong>本地化差异</strong>：时区、语言、货币格式，服务端和用户端可能不一致。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>解法</strong>通常是：把这类「只能在客户端确定」的内容，<strong>推迟到水合之后再渲染</strong>——比如用一个 <code>useEffect</code> 在客户端挂载后才设置它（首屏先渲染一个占位 / 服务端能确定的值）。框架也提供了专门的出口：如 <code>suppressHydrationWarning</code>(React)、<code>&lt;ClientOnly&gt;</code>（各框架的「仅客户端」组件）。<strong>记住这条铁律：服务端和客户端的首次渲染必须一致</strong>——违反它，就等着水合失配的告警和闪烁。</p></div><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>水合是 SSR 的「点睛」步骤：它让客户端 JS 接管服务端发来的静态 HTML，装上事件与状态，把「死」的页面救「活」。代价是同一份渲染在两端各跑一遍（慢、占 CPU），还留下了「看得见点不动」的空档和「水合失配」这个大坑。</p><p>现在我们有了三块地基：CSR 的痛、SSR 是什么、水合。是时候把它们和另外两个词——SSG、ISR——摆在一起，画一张全景图，看清「渲染」到底有哪几种玩法、各自的取舍。这张图也是后面缓存讨论的坐标系。👉 <a href="/Front2Full/manual/computer-programming/ssr/rendering-spectrum">渲染光谱：CSR / SSR / SSG / ISR 一图看清</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] React 官方文档.「hydrateRoot.」<a href="https://react.dev/reference/react-dom/client/hydrateRoot" target="_blank" rel="noreferrer">https://react.dev/reference/react-dom/client/hydrateRoot</a> —— 水合 API 与失配说明。</li><li>[2] web.dev.「Rendering on the Web — Hydration.」<a href="https://web.dev/articles/rendering-on-the-web" target="_blank" rel="noreferrer">https://web.dev/articles/rendering-on-the-web</a> —— 水合的代价与 TTI。</li><li>[3] Addy Osmani.「The Cost of JavaScript.」<a href="https://medium.com/@addyosmani" target="_blank" rel="noreferrer">https://medium.com/@addyosmani</a> —— JS 解析 / 执行开销与设备差异。</li></ul>`,27)])])}const k=a(r,[["render",e]]);export{c as __pageData,k as default};
